				string msg = $"\r\n[状态同步]：Start{DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}";
DateTime StartTime = DateTime.Now;
bool IsWriteLog = false;
try
{
	List<SystemSynchronizationEntity> SystemSynchronization = null;
	ISystemSynchronizationRepository SystemSynchronizationRepository = new SystemSynchronizationRepository();
	SystemSynchronization = SystemSynchronizationRepository.FindList(t => t.syn_status == 0 && t.syn_direction == 1).OrderBy(t => t.ope_time).ToList();

	if (SystemSynchronization != null && SystemSynchronization.Count > 0)
	{
		WCSTOWMS wms = new WCSTOWMS();
		AutoScanApp ausc = new AutoScanApp();
		foreach (var item in SystemSynchronization)
		{
			IsWriteLog = true;
			ToWmsNotifyTaskStatusRequest ToWmsNotifyTaskStatusRequest = new ToWmsNotifyTaskStatusRequest();
			ToWmsNotifyTaskStatusRequest.reqId = Guid.NewGuid().ToString();
			ToWmsNotifyTaskStatusRequest.status = item.ope_type;
			ToWmsNotifyTaskStatusRequest.taskNo = item.task_no;
			ToWmsNotifyTaskStatusRequest.loc = item.reverse_2;
			ToWmsNotifyTaskStatusRequest.errCode = item.ope_memo;
			ToWmsNotifyTaskStatusRequest.deviceNo = item.ope_device_no;
			ToWmsNotifyTaskStatusRequest.reqTime = DateTime.Now.ToString();

			var wcor = wms.FeedInfoToWms(ToWmsNotifyTaskStatusRequest, out string errorMsg);
			if (wcor == null || wcor.code != 200)
			{
				msg += $"\r\n\t任务状态更新请求失败，上报任务号: {item.task_no};错误信息：{errorMsg}{DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}";
				continue;
			}
			msg += $"\r\n\t任务状态更新请求成功{DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}";
			item.syn_status = 1;
			item.syn_time = DateTime.Now;
			bool resultms = ausc.SystemSynchronizationUpdate(item, out string err);
			if (!resultms)
			{
				msg += $"\r\n\t任务状态更新数据库失败，请求信息：[{item.task_no}];错误信息：{err}{DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}";
			}
			msg += $"\r\n\t数据提交成功{DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}";
		}
	}

}
catch (Exception ex)
{
	msg += $"\r\n\t[Error]{ex}";
	Conn.WCSLOG.Error(1, "同步任务状态至WMS", 1, msg);
}
finally
{
	if (IsWriteLog)
	{
		msg += $"\r\n\t[EndTime]{DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss:fff")}";
		msg += $"\r\n\t[SpanTime]{DateTime.Now - StartTime}";
		msg += $"\r\n[状态同步]End";
		Conn.WCSLOG.Info(1, "同步任务状态至WMS", 1, msg);
	}
}

